# If MELD(i) > 11, perform additional MELD calculation
if MELD_i > 11:
    MELD = MELD_i + 1.32 * (137 - sodium) - (0.033 * MELD_i * (137 - sodium))
    MELD = min(MELD, 40)
else:
    MELD = MELD_i

