FiO2 = 0.21
platelets = 50
bilirubin = 3
MAP = 0
GCS = 13
creatinine = 2.5

# Calculate the respiratory component
if PaO2 / FiO2 >= 400:
    resp = 0
elif PaO2 / FiO2 >= 300 and PaO2 / FiO2 < 400:
    resp = 1
elif PaO2 / FiO2 >= 200 and PaO2 / FiO2 < 300:
    resp = 2
elif PaO2 / FiO2 >= 100 and PaO2 / FiO2 < 200 and mechanical_ventilation == True:
    resp = 3
else:
    resp = 4

# Calculate the coagulation component (platelets)
if platelets >= 150:
    coag = 0
elif platelets >= 100 and platelets < 150:
    coag = 1
elif platelets >= 50 and platelets < 100:
    coag = 2
elif platelets >= 20 and platelets < 50:
    coag = 3
else:
    coag = 4

# Calculate the liver component (bilirubin)
if bilirubin < 1.2:
    liver = 0
elif bilirubin >= 1.2 and bilirubin < 1.9:
    liver = 1
elif bilirubin >= 2 and bilirubin < 5.9:
    liver = 2
elif bilirubin >= 6 and bilirubin < 11.9:
    liver = 3
else:
    liver = 4

# Calculate the cardiovascular component (MAP)
if MAP == 0:
    cardio = 0
elif MAP > 0 and MAP < 70:
    cardio = 1
elif MAP >= 70 and (DOPamine <= 5 or DOBUTamine > 0):
    cardio = 2
elif MAP >= 70 and (DOPamine > 5 and EPINEPHrine <= 0.1 and norEPINEPHrine <= 0.1):
    cardio = 3
else:
    cardio = 4

# Calculate the neurological component (GCS)
if GCS == 15:
    neuro = 0
elif GCS >= 13 and GCS < 15:
    neuro = 1
elif GCS >= 10 and GCS < 13:
    neuro = 2
elif GCS >= 6 and GCS < 10:
    neuro = 3
else:
    neuro = 4

# Calculate the renal component (creatinine and urine output)
if creatinine < 1.2 and urine_output >= 500:
    renal = 0
elif (creatinine >= 1.2 and creatinine < 1.9) or (urine_output >= 200 and urine_output < 500):
    renal = 1
elif (creatinine >= 2 and creatinine < 3.4) or (urine_output < 200):
    renal = 2
elif (creatinine >= 3.5 and creatinine < 4.9) or (urine_output < 500):
    renal = 3
else:
    renal = 4

# Calculate the total SOFA score
SOFA_score = resp + coag + liver + cardio + neuro + renal
print(SOFA_score)'}, 'log': "
